    fsp = "FSP"
    aashell = "AASHELL"
    lxc = "LXC"
    fhnet = "FHNET"

    _re_fct_prompt = r"root@((fct(-\d+[a-z])?)|(asc-\da)):.*>"
    _re_fsp_4g_prompt = r"root@fsp(\d+|-\d+[a-z]):.*>"
    _re_fsp_5g_prompt = r"(root@)?((aspa?-\d+[a-z])|(asc-\d+[b-z])):.*(>|#)"
    _re_fsp_prompt = f"({_re_fsp_4g_prompt}|{_re_fsp_5g_prompt})"
    _re_aashell_prompt = r"AaShell>"
    _re_lxc_legacy_prompt = r"root@0x[a-f0-9]+.*?>"
    _re_lxc_new_prompt = r"root@ASI\d+.*?>"
    _re_lxc_prompt = f"({_re_lxc_legacy_prompt}|{_re_lxc_new_prompt})"
    _re_fhnet_prompt = r"root@FHNET\d+.*:"

    def __init__(
        self,
        sm_params,
        name=None,
        io_connection=None,
        io_type=None,
        variant=None,
        io_constructor_kwargs=None,
        initial_state=None,
        lazy_cmds_events=False,
    ):
        """
        Create Unix device communicating over io_connection.

        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: External-IO connection connection type
        :param variant: External-IO connection variant
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: Initial state for device
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        sm_params = sm_params.copy()
        initial_state = initial_state if initial_state is not None else AirScale3.fct
        self._login_via_master = self._is_master_in_sm_params(sm_params=sm_params)

        super(AirScale3, self).__init__(
            sm_params=sm_params,
            name=name,
            io_connection=io_connection,
            io_type=io_type,
            variant=variant,
            io_constructor_kwargs=io_constructor_kwargs,
            initial_state=initial_state,
            lazy_cmds_events=lazy_cmds_events,
        )
        self.logger = logging.getLogger("moler.air_scale")
        self._alternative_ssh_params_fct = None
        self._ssh_to_fct = "plain"  # plain for standard ssh or key in _alternative_ssh_params_fct.

    def goto_state(
        self, state, timeout=-1, rerun=0, send_enter_after_changed_state=False, log_stacktrace_on_fail=True,
            keep_state=False, timeout_multiply=1.0, sleep_after_changed_state=0.5
    ):
        """
        Goes to specific state.

        :param state: Name to state to change on the device.
        :param timeout: Timeout for changing state, if negative then timeout from commands are taken.
        :param rerun: How many times rerun the procedure before it fails.
        :param send_enter_after_changed_state: If True then enter is sent after state is changed. False nothing is sent.
        :param log_stacktrace_on_fail: Set True to have stacktrace in logs when failed, otherwise False.
        :param keep_state: if True and state is changed without goto_state then device tries to change state to state
        defined by goto_state.
        :param timeout_multiply: how many times multiply passed timeout to get final timeout.
        :param sleep_after_changed_state:
        :return: None
        :raise: DeviceChangeStateFailure if cannot change the state of device.
        """
        return super(AirScale3, self).goto_state(
            state=state,
            timeout=timeout,
            rerun=rerun,
            send_enter_after_changed_state=send_enter_after_changed_state,
            log_stacktrace_on_fail=log_stacktrace_on_fail,
            keep_state=keep_state,
            timeout_multiply=timeout_multiply,
            sleep_after_changed_state=sleep_after_changed_state
        )

    def change_container_id(self, container_id):
        """
        Change container ID.

        :param container_id:    ASICNTR container ID eg:  0xe019
        :return: None
        """
        lxc_state = self._configurations[AirScale3.connection_hops][AirScale3.fct][AirScale3.lxc]
        lxc_state["command_params"]["name"] = container_id

    def change_fhnet_container_id(self, container_id):
        """
        Change container ID.

        :param container_id:    ASICNTR container ID eg:  0xe019
        :return: None
        """
        lxc_state = self._configurations[AirScale3.connection_hops][AirScale3.fct][AirScale3.fhnet]
        lxc_state["command_params"]["name"] = container_id

    _container_id_ps = {
        "lxc": re.compile(r"-n (?P<CONTAINER_ID>\S+) .+ /ffs/run/swpool/ASICNTR"),
        "fhnet": re.compile(r"/ram/node_FHNET[08]0/lxc.cfg -n (?P<CONTAINER_ID>\S+)"),
    }

    def detect_container_id(self, max_try=5, container_type="lxc"):
        """
        Change container id dynamically.

        :return: id of container
        """
        attempt = 0
        container_id = None
        container_id_ps = AirScale3._container_id_ps[container_type]

        while attempt <= max_try and container_id is None:
            attempt += 1
            try:
                ps_cmd = self.get_cmd(cmd_name="ps", cmd_params={"options": "-ef"})
                result = ps_cmd()
                for process in result:
                    m = re.search(container_id_ps, process["CMD"])
                    if m:
                        container_id = m.group("CONTAINER_ID")
                        break
            except MolerException:
                continue
        if container_id:
            if container_type == "lxc":
                self.change_container_id(container_id)
            else:
                self.change_fhnet_container_id(container_id)
        return container_id

    def set_fct_address(self, address="192.168.255.129"):
        """
        Change FCT address.

        :param address: Address of FCT.
        :return: None
        """
        fct_state = self.__get_fct_state()
        fct_state["command_params"]["host"] = address

    def get_fct_address(self):
        """
        Get FCT address.

        :return: None
        """
        fct_state = self.__get_fct_state()
        return fct_state["command_params"]["host"]

    def set_fsp_address(self, address="192.168.253.22"):
        """
        Change FSP address.

        :param address: Address of FSP.
        :return: None
        """
        fsp_state = self._configurations[AirScale3.connection_hops][AirScale3.fct][AirScale3.fsp]
        fsp_state["command_params"]["host"] = address

    def get_fsp_address(self):
        """
        Get FSP address.

        :return: None
        """
        fsp_state = self._configurations[AirScale3.connection_hops][AirScale3.fct][AirScale3.fsp]
        return fsp_state["command_params"]["host"]

    def __get_fct_state(self):
        possible_states = [[AirScale3.proxy_pc, AirScale3.fct],
                           [AirScale3.unix_local, AirScale3.fct],
                           [AirScale3.master, AirScale3.fct]]
        fct_state = None
        for states in possible_states:
            try:
                fct_state = self._configurations[AirScale3.connection_hops][states[0]][states[1]]
                return fct_state
            except KeyError:
                pass

        return fct_state

    def _is_master_in_sm_params(self, sm_params):
        """
        Check that SECONDARY_SMOD state is inside sm configuration.

        :param sm_params: sm configuration
        :return: True when SECONDARY_SMOD state exist, otherwise False
        """
        return self._is_proxy_pc_in_sm_params(sm_params=sm_params, proxy=AirScale3.master)

    def _get_default_sm_configuration(self):
        """
        Create State Machine default configuration for AirScale3.

        :return: default sm configuration.
        """
        config = super(AirScale3, self)._get_default_sm_configuration()
        if self._use_proxy_pc:
            if self._login_via_master:
                default_config = self._get_default_sm_configuration_with_proxy_pc_with_master_and_fct()
            else:
                default_config = self._get_default_sm_configuration_with_proxy_pc_without_master_and_fct()
        else:
            if self._login_via_master:
                default_config = self._get_default_sm_configuration_without_proxy_pc_with_master_and_fct()
            else:
                default_config = self._get_default_sm_configuration_without_proxy_pc_without_master_and_fct()
        self._update_dict(config, default_config)
        return config

