    def _prepare_alternative_params_for_ssh_fct(self, source_state, dest_state):
        """
        Prepare ssh params for alternative connection to FCT.

        :param source_state: device source state.
        :param dest_state: device destination state.
        :return: None
        """
        self._alternative_ssh_params_fct = {}  # delete already known params (if any)

        alive = "-o ServerAliveInterval=7 -o ServerAliveCountMax=2"

        # 1576 - single key
        state_dict = copy_dict(src=self._configurations[AirScale3.connection_hops][source_state][dest_state], deep_copy=True)
        command_params = state_dict["command_params"]
        proxy_host = command_params["host"]
        command_params["host"] = "127.0.0.1"
        proxy_command = f"ssh -i serviceuser_key {alive} -W %h:%p -p 22 serviceuser@{proxy_host}"
        options = f'-Ao ProxyCommand="{proxy_command}" {alive} -i serviceuser_key'
        command_params["options"] = options
        self._alternative_ssh_params_fct["1576_single_key"] = state_dict

        # 1576 - two keys
        state_dict = copy_dict(src=self._configurations[AirScale3.connection_hops][source_state][dest_state], deep_copy=True)
        command_params = state_dict["command_params"]
        proxy_host = command_params["host"]
        command_params["host"] = "127.0.0.1"
        proxy_command = f"ssh -i serviceuser_key {alive} -W %h:%p -p 22 serviceuser@{proxy_host}"
        options = f'-Ao ProxyCommand="{proxy_command}" {alive} -i toor4nsn_key'
        command_params["options"] = options
        self._alternative_ssh_params_fct["1576_two_keys"] = state_dict

    def _execute_alternative_ssh_to_fct(self, source_state, dest_state, timeout=-1, ssh_type=None):
        """
        Execute action to change state for FR1576 mmWave.

        :param source_state: device source state.
        :param dest_state: device destination state.
        :param timeout: transition timeout.
        :return: None.
        """
        if self._alternative_ssh_params_fct is None:
            self._prepare_alternative_params_for_ssh_fct(source_state, dest_state)

        last_ex = WrongUsage("No command finished with success nor failure. No command to ssh? Please contact ta_moler team for assistance.")
        if ssh_type is not None:
            try:
                self._try_execute_given_ssh_type(timeout, ssh_type)
                return  # If ssh succeeded.
            except MolerException as ex:
                last_ex = ex

        ssh_type_l = None
        for ssh_type_l in self._alternative_ssh_params_fct:
            if ssh_type_l == ssh_type:
                continue
            try:
                self._log(logging.INFO, f"Try to use '{ssh_type_l}' ssh.")
                self._try_execute_given_ssh_type(timeout, ssh_type_l)
                self._ssh_to_fct = ssh_type_l  # Command finished with success so remember type and leave method.
                return
            except MolerException as ex:
                last_ex = ex
        if last_ex:
            raise last_ex  # No command finished with success.
        else:
            self._log(
                logging.INFO,
                f"Unexpected lack of object to raise. source_state='{source_state}', dest_state='{dest_state}', timeout='{timeout}', ssh_type='{ssh_type_l}', ssh_type_l='{ssh_type}', state hops={self._state_hops}",
            )
            raise WrongUsage("No command finished with success nor failure. No command to ssh? Please contact ta_moler team for assistance.")

    def _try_execute_given_ssh_type(self, timeout, ssh_type):
        """
        Try to execute command to ssh to FCT.

        :param source_state: device source state.
        :param dest_state: device destination state.
        :param timeout: transition timeout
        :param ssh_type: type of ssh.
        :return: None
        :raises: MolerException if ssh failed.
        """
        configurations = self._alternative_ssh_params_fct[ssh_type]
        command_name = configurations["execute_command"]
        command_params = configurations["command_params"]
        command_timeout = self.calc_timeout_for_command(timeout, command_params)
        command_params_without_timeout = self._parameters_without_timeout(parameters=command_params)
        command = self.get_cmd(cmd_name=command_name, cmd_params=command_params_without_timeout)
        command(timeout=command_timeout)

    def _execute_ssh_to_fct(self, source_state, dest_state, timeout=-1):
        """
        Execute action to change state.

        :param source_state: device source state.
        :param dest_state: device destination state.
        :param timeout: transition timeout.
        :return: None.
        """
        if self._ssh_to_fct != "plain":
            try:
                self._log(logging.INFO, "Try double ssh to FCT.")
                self._execute_alternative_ssh_to_fct(source_state, dest_state, timeout, self._ssh_to_fct)
            except (CommandFailure, CommandTimeout):
                self._log(logging.INFO, "Alternative ssh to FCT failed. Try plain ssh.")
                self._execute_command_to_change_state(source_state, dest_state, timeout)
                self._ssh_to_fct = "plain"
        else:
            try:
                self._log(logging.INFO, "Try plain ssh to FCT.")
                self._execute_command_to_change_state(source_state, dest_state, timeout)
            except (CommandFailure, CommandTimeout):
                self._log(logging.INFO, "Plain ssh to FCT failed. Try alternative ssh.")
                self._execute_alternative_ssh_to_fct(source_state, dest_state, timeout)

    def _execute_command_fct_lxc(self, source_state, dest_state, timeout=-1):
        """
        Execute command to change state from fct to lxc.

        :param source_state: device source state.
        :param dest_state: device destination state.
        :param timeout: transition timeout.
        :return: None.
        :raise DeviceChangeStateFailure if cannot detect container id
        """
        lxc_state = self._configurations[AirScale3.connection_hops][AirScale3.fct][AirScale3.lxc]
        container_id = lxc_state["command_params"]["name"]
        if container_id is None:
            container_id = self.detect_container_id(container_type="lxc")
            if container_id is None:
                raise DeviceChangeStateFailure(device=self.name, exception="Cannot get dynamically container id for LXC.")
        self._execute_command_to_change_state(source_state=source_state, dest_state=dest_state, timeout=timeout)

    def _execute_command_fct_fhnet(self, source_state, dest_state, timeout=-1):
        """
        Execute command to change state from fct to fhnet.

        :param source_state: device source state.
        :param dest_state: device destination state.
        :param timeout: transition timeout.
        :return: None.
        :raise DeviceChangeStateFailure if cannot detect container id
        """
        fhnet_state = self._configurations[AirScale3.connection_hops][AirScale3.fct][AirScale3.fhnet]
        container_id = fhnet_state["command_params"]["name"]
        if container_id is None:
            container_id = self.detect_container_id(container_type="fhnet")
            if container_id is None:
                raise DeviceChangeStateFailure(device=self.name, exception="Cannot get dynamically container id for FHNET.")
        self._execute_command_to_change_state(source_state=source_state, dest_state=dest_state, timeout=timeout)

