    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(AirScale3, self)._get_packages_for_state(state, observer)

        if not available:
            if state == AirScale3.fct or state == AirScale3.master:
                available = {
                    AirScale3.cmds: ["moler.cmd.unix", "ta_moler.cmd.shared.nokiaunix", "ta_moler.cmd.shared.enblinux", "ta_moler.cmd.airscale.fct"],
                    AirScale3.events: ["moler.events.shared", "moler.events.unix", "ta_moler.events.airscale"],
                }
            elif state == AirScale3.aashell:
                available = {
                    AirScale3.cmds: ["ta_moler.cmd.shared.aashell", "ta_moler.cmd.airscale.aashell"],
                    AirScale3.events: ["moler.events.shared", "moler.events.unix", "ta_moler.events.airscale"],
                }
            elif state == AirScale3.fsp:
                available = {
                    AirScale3.cmds: ["moler.cmd.unix", "ta_moler.cmd.shared.nokiaunix", "ta_moler.cmd.shared.enblinux", "ta_moler.cmd.airscale.fsp"],
                    AirScale3.events: ["moler.events.shared", "moler.events.unix", "ta_moler.events.airscale"],
                }
            elif state == AirScale3.lxc:
                available = {
                    AirScale3.cmds: ["moler.cmd.unix", "ta_moler.cmd.shared.nokiaunix", "ta_moler.cmd.airscale.lxc"],
                    AirScale3.events: ["moler.events.shared", "moler.events.unix", "ta_moler.events.airscale"],
                }
            elif state == AirScale3.fhnet:
                available = {
                    AirScale3.cmds: ["moler.cmd.unix", "ta_moler.cmd.shared.nokiaunix", "ta_moler.cmd.airscale.fhnet"],
                    AirScale3.events: ["moler.events.shared", "moler.events.unix", "ta_moler.events.airscale"],
                }

            if available:
                return available[observer]

        return available
